package ktanesolver.module.modded.regular.sevenwires;
import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class SevenWiresSolverTest{@Test void usesTheIndicatorRuleBeforeTheFallback(){BombEntity b=new BombEntity();b.setSerialNumber("ABC124");b.setIndicators(Map.of("FRK",true,"CLR",true));SevenWiresOutput o=solve(b);assertThat(o.wirePosition()).isEqualTo(2);assertThat(o.rule()).isEqualTo(1);}@Test void fallsBackBySerialParity(){BombEntity b=new BombEntity();b.setSerialNumber("ABC124");SevenWiresOutput o=solve(b);assertThat(o.wirePosition()).isEqualTo(3);assertThat(o.rule()).isEqualTo(27);}@SuppressWarnings("unchecked")private static SevenWiresOutput solve(BombEntity b){return((SolveSuccess<SevenWiresOutput>)new SevenWiresSolver().solve(new RoundEntity(),b,new ModuleEntity(),new SevenWiresInput(13,List.of("red","blue","black","yellow","red","blue","black"),List.of(),false,false,false,false))).output();}}
